// Nâng cấp câu: o[0] luôn là đáp án đúng (sẽ được xáo trộn khi hiển thị)
const PARA = [
{q:"Many people use their phones too much.",o:["Excessive smartphone use has become widespread.","Many people use phones excessive.","Smartphone using is too much by many people."],why:"“Excessive” là tính từ đứng trước danh từ “use”. Câu 2 sai vì cần trạng từ “excessively”; câu 3 sai cấu trúc."},
{q:"Pollution is a very big problem.",o:["Pollution poses a serious threat to public health.","Pollution makes a serious threat to public health.","Pollution is a very heavy problem."],why:"Collocation đúng là “pose a threat”, không phải “make a threat”; “heavy problem” không tự nhiên trong tiếng Anh."},
{q:"The number of students went up a lot.",o:["There was a significant increase in student numbers.","The number of students increased significant.","The students number went up very much."],why:"“An increase in + N”; khi bổ nghĩa cho động từ phải dùng trạng từ “significantly”."},
{q:"Children learn a lot from their parents.",o:["Parents play a crucial role in shaping their children's behaviour.","Parents play a crucial role to shape their children's behaviour.","Parents make an important role in their children's behaviour."],why:"Cấu trúc là “play a role in + V-ing”, không dùng “to V” và không dùng “make a role”."},
{q:"The good points are more than the bad points.",o:["The advantages outweigh the disadvantages.","The advantages are outweigh the disadvantages.","The advantages outweigh than the disadvantages."],why:"“Outweigh” là động từ nên không cần “are”, và không đi với “than”."},
{q:"The government should do something about traffic jams.",o:["The government should take measures to ease traffic congestion.","The government should do measures to reduce traffic jam.","The government should take measures to easy traffic congestion."],why:"Collocation là “take measures”; “ease” là động từ, còn “easy” là tính từ."},
{q:"People in the countryside move to cities to find jobs.",o:["Many rural residents migrate to urban areas in search of employment.","Many rural residents migrate to urban areas for searching employment.","Many rural people migrates to city area to find job."],why:"Cụm cố định là “in search of”. Câu 3 sai chia động từ (migrates) và thiếu mạo từ / số nhiều."},
{q:"Smoking is very bad for your health.",o:["Smoking is extremely detrimental to health.","Smoking is extremely harmful with health.","Smoking causes very bad affects to health."],why:"Dùng “detrimental / harmful to”, không dùng “with”. “Affect” là động từ, danh từ phải là “effect” và đi với “on”."},
{q:"Because of the internet, we can get information easily.",o:["The internet has made information far more accessible.","The internet has made information more access.","Due to the internet, we can get information easy."],why:"Sau “make + O” cần tính từ “accessible”; “easy” là tính từ, bổ nghĩa động từ phải dùng “easily”."},
{q:"I agree a little with this idea.",o:["I agree with this view to some extent.","I agree this view to some extent.","I am agree with this view in some extent."],why:"Phải nói “agree with”, không dùng “am agree”; cụm đúng là “to some extent”."},
{q:"Life is more expensive now.",o:["The cost of living has risen considerably.","The cost of living has raised considerably.","The living cost has risen considerable."],why:"“Rise” là nội động từ (rise–rose–risen), còn “raise” cần tân ngữ. Bổ nghĩa động từ cần trạng từ “considerably”."},
{q:"Many young people don't have jobs.",o:["Youth unemployment remains a serious concern.","Young unemployment remains a serious concern.","Youth unemployment remain a serious concern."],why:"Cụm đúng là “youth unemployment”; chủ ngữ số ít nên động từ là “remains”."},
{q:"There are more old people than before.",o:["The proportion of elderly people has grown steadily.","The proportion of elderly people has grown steady.","The proportion of old peoples has growth steadily."],why:"Bổ nghĩa động từ cần trạng từ “steadily”; “people” đã là số nhiều; “growth” là danh từ."},
{q:"Watching TV a lot is not good for kids.",o:["Excessive screen time can have a negative impact on children.","Excessive screen time can have a negative impact to children.","Excessive screen time can make a negative effect for children."],why:"Cấu trúc đúng: “have an impact / effect on”."},
{q:"Some people think university should be free, other people think students should pay.",o:["While some argue that university should be free, others believe students should contribute to the cost.","Despite some argue that university should be free, others believe students should contribute to the cost.","Some argue that university should be free, whereas others believes students should contributing to the cost."],why:"“Despite” không đi với mệnh đề. Câu 3 sai “others believe” (số nhiều) và “should + V nguyên mẫu”."},
{q:"Many animals are dying because forests are cut down.",o:["Deforestation is pushing many species towards extinction.","Deforestation is pushing many species to extinct.","Deforestation makes many species extinction."],why:"“Towards / to + danh từ extinction”; “extinct” là tính từ."},
{q:"Online learning is convenient but it has problems.",o:["Despite its convenience, online learning has several drawbacks.","Despite it is convenient, online learning has several drawbacks.","Although its convenience, online learning has several drawback."],why:"Despite + danh từ (its convenience); Although + mệnh đề. “Several” đi với danh từ số nhiều."},
{q:"Companies should pay workers more money.",o:["Companies should offer their employees more competitive salaries.","Companies should offer their employees a more competitive salaries.","Companies should give employees salaries more competitive."],why:"Không dùng “a” với danh từ số nhiều; tính từ đứng trước danh từ."}
];

